    {
      "element_id": "prisma_2020_7_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No information about peer review of the search strategy (e.g., PRESS) or its process/tool is reported in the provided evidence."
    },
    {
      "element_id": "prisma_2020_7_e8",
      "status": "MISSING",
      "chunk_id": "text_8",
      "quote": "We conducted the literature search by using appropriate key words, accepted Medical Subject Headings words, and combinations thereof. One search approach involved using broad search terms ( e.g ., mothers OR women OR female OR adolescent OR pregnant women) combined with intervention-specific search terms such as disease names (cardiovascular diseases OR cancer OR respiration disorders OR diabetes) and NCD risk factors (tobacco use OR smoking OR diet OR nutrition OR alcohol).",
      "reason": "Although the evidence describes keywords, MeSH terms and example term combinations, it does not describe the final conceptual structure used (or explorations/development steps) when the search was not based on PICO; thus the required description of the conceptual structure is not provided."
    }
  ],
  "confidence": 60
