{
  "item_id": "PRISMA_2020_10b",
  "elements": [
    {
      "element_id": "prisma_2020_10b_e1",
      "status": "PARTIAL",
      "chunk_id": "text_10; text_5",
      "quote": "The first author extracted the features of each study ( e.g. , study design, setting, participants, components of intervention, related NCDs, and main outcomes) and entered them into a standardized form.\n\nParticipants of the interventions included women of reproductive age, defined as those aged 15-49 years according to the WHO; mothers; children < 5 years old; and RMNCH care service providers from lowand middle-income countries.",
      "reason": "The manuscript explicitly lists the other variables extracted (study design, setting, participants, intervention components, related NCDs, main outcomes) and provides a definition for participants, but it does not provide definitions for the other listed variables (e.g., study design, setting, components of intervention, related NCDs, main outcomes)."
    },
    {
      "element_id": "prisma_2020_10b_e2",
      "status": "MISSING",
      "chunk_id": "text_10; text_13",
      "quote": "The first author extracted the features of each study ( e.g. , study design, setting, participants, components of intervention, related NCDs, and main outcomes) and entered them into a standardized form. The second author checked all data for accuracy and completeness. To resolve any discrepancies, the two authors discussed until they reached an agreement.\n\nBoth assessed studies lacked information related to the blinding during data collection or implementation.",
      "reason": "The text describes data extraction procedures and resolving discrepancies but does not describe any assumptions made about missing or unclear study information or how missing data were interpreted; no explicit assumptions are reported."
    },
    {
      "element_id": "prisma_2020_10b_e3",
      "status": "MISSING",
      "chunk_id": "text_10; text_3",
      "quote": "The first author extracted the features of each study ... and entered them into a standardized form.\n\nWe conducted a systematic review following the guidelines of the Cochrane Collaboration ( 19 ) and the four phases indicated in the Preferred Reporting Items for Systematic Reviews and Meta-Analyses (PRISMA) Statement ( 20 ).",
      "reason": "Although the review followed Cochrane and PRISMA guidance and used a 'standardized form' for extraction, the manuscript does not cite or name any specific tool or source used to determine which data items to collect (no citation of a data extraction template or checklist used to select items)."
    }
  ],
  "confidence": 80
}

{
  "item_id": "PRISMA_2020_11",
  "elements": [
    {
      "element_id": "prisma_2020_11_e1",
      "status": "PARTIAL",
      "chunk_id": "text_11",
      "quote": "For randomized controlled trials, the risk of bias was evaluated using the \"risk of bias\" tool presented in the Cochrane Handbook for Systematic Reviews of Interventions ( 19 ). ... To assess non-randomized intervention studies, we used \"a Cochrane risk of bias assessment tool: for non-randomized studies of interventions (ACROBAT-NRSI)\" ( 25 ).",
      "reason": "The manuscript names the tools used for randomized trials (Cochrane 'risk of bias' tool) and non-randomized studies (ACROBAT-NRSI) but does not specify tool versions or editions."
    },
    {
      "element_id": "prisma_2020_11_e2",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Specifically, we assessed the risk of bias in the following seven domains: sequence generation, allocation concealment, blinding of participants and outcome assessors, incomplete outcome data, selective outcome reporting, and other potential threats to validity. ... For nonrandomized intervention studies, we evaluated the risk of bias using the following seven domains: confounding, selection of participants, intervention measurements, departures from intended interventions, missing data, outcome measurement, and selective outcome reporting.",
      "reason": "The domains/items assessed by the risk-of-bias tools are explicitly listed for both randomized and non-randomized studies."
    },
    {
      "element_id": "prisma_2020_11_e3",
      "status": "PARTIAL",
